python3 << 'PYEOF'
with open('src/context/SocketContext.js', 'r', encoding='utf-8') as f:
    content = f.read()

# 1. إضافة حالة serverIp
anchor1 = "  const [walkieSettings, setWalkieSettings] = useState({ enabled: true, mutedUsers: [] });"
addition1 = anchor1 + "\n  const [serverIp, setServerIp] = useState(null);"
assert content.count(anchor1) == 1
content = content.replace(anchor1, addition1)

# 2. حفظ الـ IP عند الاتصال
anchor2 = """    return new Promise((resolve, reject) => {
      const color = randomColor();
      setUserName(name);
      setAvatarColor(color);"""
addition2 = """    return new Promise((resolve, reject) => {
      const color = randomColor();
      setUserName(name);
      setAvatarColor(color);
      setServerIp(ip);"""
assert content.count(anchor2) == 1
content = content.replace(anchor2, addition2)

# 3. تعديل publishPost ليقبل ملف مرفق
anchor3 = """  const publishPost = useCallback((text, image = null) => {
    if (!text?.trim() && !image) return;

    if (socketRef.current?.connected) {
      socketRef.current.emit("newPost", {
        text: text?.trim() || '',
        image: image || null,
      });
    } else {
      const newPost = {
        id: Date.now().toString(),
        authorName: userName || 'مستخدم',
        avatarColor: avatarColor,
        text: text?.trim() || '',
        image: image || null,
        likes: [],
        comments: [],
        createdAt: new Date().toISOString(),
      };
      setPosts((prev) => [newPost, ...prev]);
    }
  }, [userName, avatarColor]);"""

addition3 = """  const publishPost = useCallback((text, image = null, file = null) => {
    if (!text?.trim() && !image && !file) return;

    if (socketRef.current?.connected) {
      socketRef.current.emit("newPost", {
        text: text?.trim() || '',
        image: image || null,
        file: file || null,
      });
    } else {
      const newPost = {
        id: Date.now().toString(),
        authorName: userName || 'مستخدم',
        avatarColor: avatarColor,
        text: text?.trim() || '',
        image: image || null,
        file: file || null,
        likes: [],
        comments: [],
        createdAt: new Date().toISOString(),
      };
      setPosts((prev) => [newPost, ...prev]);
    }
  }, [userName, avatarColor]);"""

assert content.count(anchor3) == 1, f"وجدت {content.count(anchor3)} تكرار بدل 1"
content = content.replace(anchor3, addition3)

# 4. إضافة serverIp لقيمة الـ context
anchor4 = "        walkieSettings,\n        socket: socketRef.current,"
addition4 = "        walkieSettings,\n        serverIp,\n        socket: socketRef.current,"
assert content.count(anchor4) == 1
content = content.replace(anchor4, addition4)

with open('src/context/SocketContext.js', 'w', encoding='utf-8') as f:
    f.write(content)

print("تم بنجاح ✅")
PYEOF
